sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?song ?releaseDate
WHERE {
  VALUES ?song { dbr:Come_with_Me_(Pure_Imagination) dbr:Hold_on_Me_(Grinspoon_song) }
  OPTIONAL { ?song dbp:releaseDate ?dbpDate . }
  OPTIONAL { ?song dbo:releaseDate ?dboDate . }
  BIND (COALESCE(?dbpDate, ?dboDate) AS ?releaseDate)
}
LIMIT 100

